const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' && !Array.isArray(input.body) ? input.body : input;
const errors = [];
const safe = body && typeof body === 'object' && !Array.isArray(body) ? body : {};

if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  errors.push({ field: 'body', message: 'Le corps doit etre un objet JSON.' });
}

const allowed = ['loginuser', 'nomuser', 'idrole', 'teluser', 'adruser', 'codeEtablissement', 'refuser'];
for (const key of Object.keys(safe)) {
  if (!allowed.includes(key)) errors.push({ field: key, message: 'Champ non autorise.' });
}

const isText = (value) => typeof value === 'string' && value.trim().length > 0;

if (!isText(safe.loginuser)) errors.push({ field: 'loginuser', message: 'Valeur texte non vide requise.' });
else if (safe.loginuser.trim().length > 100) errors.push({ field: 'loginuser', message: '100 caracteres maximum.' });
if (!isText(safe.nomuser)) errors.push({ field: 'nomuser', message: 'Valeur texte non vide requise.' });
else if (safe.nomuser.trim().length > 200) errors.push({ field: 'nomuser', message: '200 caracteres maximum.' });
if (!isText(safe.idrole)) errors.push({ field: 'idrole', message: 'Valeur texte non vide requise.' });
if (!isText(safe.teluser)) errors.push({ field: 'teluser', message: 'Personnel obligatoire : sans lui le compte ne peut pas se connecter' });
if (!isText(safe.adruser)) errors.push({ field: 'adruser', message: 'Direction obligatoire : sans elle le compte ne peut pas se connecter' });
if (!isText(safe.codeEtablissement)) errors.push({ field: 'codeEtablissement', message: 'Valeur texte non vide requise.' });

return [{ json: { ok: errors.length === 0, errors, payload: safe } }];

const api = $input.first().json || {};
const doublons = Array.isArray(api.doublons) ? api.doublons : [];
const liste = doublons.map((d) => 'ID ' + (d && d.id != null ? d.id : '') + ' - ' + (d && d.nom != null ? d.nom : '')).join(' ; ');
const message = doublons.length > 0 ? 'Doublons detectes : ' + liste + '.' : '';
return [{ json: { valide: true, ecrit: false, statut: doublons.length > 0 ? 'A_VERIFIER' : 'VALIDE', doublons: doublons, message: message } }];
